sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionado = "";
  $scope.dadosVisiveis = null;
  $scope.isFading = false;

  function carregarDados(ano) {
    $scope.isFading = true;
    $timeout(function() {
      if (ano === '' || ano == null) {
        $scope.dadosVisiveis = null;
        $scope.isFading = false;
        return;
      }

      spUtil.get('widget_despesas_porcentagem_ano', { filtro_ano: ano }).then(function(response) {
        if (response.data && response.data.dados && response.data.dados.length > 0) {
          $scope.dadosVisiveis = response.data.dados[0];
        } else {
          $scope.dadosVisiveis = null;
        }
        $scope.isFading = false;
      });
    }, 500);
  }

  $rootScope.$on('anoSelecionado', function(evt, ano) {
    $scope.anoSelecionado = ano;
    carregarDados(ano);
  });

  carregarDados(new Date().getFullYear());
}

sp_widget.css:
div, h2, {
	font-family: 'Roboto Flex', sans-serif;
}

.report-widget {
    border-radius: 12px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
    background-color: #fff;
    margin-top: 24px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    font-family: 'Roboto Flex', sans-serif;
    /* Transição para o fade + movimento vertical */
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
  }

  .report-widget.panel.fade-out {
    opacity: 0;
    visibility: hidden;
    transform: translateY(20px);
  }

  .panel-heading {
    font-family: 'Roboto Flex', sans-serif;
    background-color: #e0e0e0; /* fundo cinza claro */
    padding: 12px 16px;
    border-bottom: 1px solid #ccc;
    border-top-left-radius: 12px;
    border-top-right-radius: 12px;
  }

  .panel-title {
    font-family: 'Roboto Flex', sans-serif;
   	margin: 0;
    font-size: 1.8rem;
    color: #333;
    text-align: center;
    font-size: 1.2em;
  }

  .panel-body {
    font-family: 'Roboto Flex', sans-serif;
    padding: 16px;
    flex: 1;
    width: 100%;
    /* text-align e fontes definidas inline para facilitar ajuste */
  }

  /* Transição da mensagem "Nenhum dado" */
  .mensagem {
    opacity: 0;
    visibility: hidden;
    transform: translateY(20px);
    transition: opacity 0.5s ease-in-out, visibility 0.5s ease-in-out, transform 0.5s ease-in-out;
    height: 0;
    overflow: hidden;
  }

  .mensagem.show {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    height: auto;
  }

sp_widget.script:
(function() {
  function formatarNumero(valor, divisor, sufixo) {
    var resultado = (valor / divisor).toFixed(3); // fixa 3 casas
    // insere separador de milhar com expressão regular
    resultado = resultado.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    return resultado + ' ' + sufixo;
  }

  var anoFiltrado = (typeof input !== 'undefined' && input.filtro_ano) ? input.filtro_ano : '';
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');

  if (anoFiltrado) {
    gr.addQuery('u_ano', anoFiltrado);
  }

  gr.orderByDesc('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    var despesaLiquida = parseFloat(gr.getValue('u_despesa_liquida_pedidos')) || 0;

    var valorFormatado;
    if (despesaLiquida >= 1000000000) {
      valorFormatado = formatarNumero(despesaLiquida, 1000000000, 'BI');
    } else {
      valorFormatado = formatarNumero(despesaLiquida, 1000000, 'MI');
    }

    dados.push({
      ano: gr.getValue('u_ano'),
      despesaLiquida: despesaLiquida,
      receitaCorrente: parseFloat(gr.getValue('u_receita_corrente_liquida')) || 0,
      comprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0,
      limiteAlerta: parseFloat(gr.getValue('u_limite_de_alerta')) || 0,
      limitePrudencial: parseFloat(gr.getValue('u_limite_prudencial')) || 0,
      limiteMaximo: parseFloat(gr.getValue('u_limite_maximo')) || 0,
      valorDespesaFormatado: valorFormatado
    });
  }

	//gs.addInfoMessage(JSON.stringify(dados))

  data.dados = dados;
})();
